        int[] lps = new int[m];
        int len = 0;
        for (int i = 1; i < m; ) {
            if (pattern.get(i).equals(pattern.get(len))) {
                lps[i++] = ++len;
            } else if (len > 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
