        }

        int j = 0;
        for (int i = 0; i < text.size(); i++) {
            Integer tok = text.get(i);
            while (j > 0 && !tok.equals(pattern.get(j))) {
                j = lps[j - 1];
            }
            if (tok.equals(pattern.get(j))) {
                j++;
                if (j == m) {
                    return true;
                }
            }
        }
        return false;
    }

    private void serialize(TreeNode node, List<Integer> out) {
        if (node == null) {
            out.add(NULL_SENTINEL);
            return;
